23	class ProbeIdentitySource final
24	    : public market_data::SourceEventIdentitySource {
25	public:
26	  std::optional<contracts::SourceEventId> next() override {
27	    contracts::SourceEventId::bytes_type bytes{};
28	    bytes.front() = 1;
29	    for (std::size_t index = 0; index < sizeof(next_); ++index) {
30	      bytes[bytes.size() - 1 - index] =
31	          static_cast<std::uint8_t>(next_ >> (index * 8U));
32	    }
33	    ++next_;
34	    return contracts::SourceEventId::from_bytes(bytes);
35	  }
36	
37	private:
38	  std::uint64_t next_{1};
39	};
