41	class ProbeConsumer final : public market_data::SourceEventConsumer {
42	public:
43	  bool accept(const sdk::SourceEvent &event) override {
44	    if (event.capture_sequence() != count_ + 1 ||
45	        event.payload_digest().coverage !=
46	            sdk::DigestCoverage::CompletePayload) {
47	      return false;
48	    }
49	    ++count_;
50	    return true;
51	  }
52	
53	  [[nodiscard]] std::uint64_t count() const noexcept { return count_; }
54	
55	private:
56	  std::uint64_t count_{};
57	};
